const metrics = $node['Query Fleet Metrics'].json;
const aiSummary = $node['Generate AI Executive Summary'].json?.data?.answer || 'AI summary unavailable';
const topRigs = $node['Top Rigs by Activity'].json || [];
const date = new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' });

let rigTable = '<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Rig</th><th>Failures</th><th>NPT Hours</th></tr>';
for (const rig of topRigs) {
  rigTable += `<tr><td>${rig.rigName}</td><td>${rig.failureCount}</td><td>${rig.nptHours?.toFixed(1)}</td></tr>`;
}
rigTable += '</table>';

const html = `
<html><body style="font-family:Arial;max-width:700px;margin:0 auto">
<h1 style="color:#1a365d">🛢 RigMind AI™ — Daily Executive Report</h1>
<p style="color:#666">${date}</p>
<hr/>
<h2>📊 Fleet Overview</h2>
<table border="1" cellpadding="8" style="border-collapse:collapse;width:100%">
<tr><td><b>Total Rigs</b></td><td>${metrics.totalRigs}</td><td><b>Open Failures</b></td><td style="color:${metrics.openFailures>5?'red':'green'}">${metrics.openFailures}</td></tr>
<tr><td><b>Critical Failures</b></td><td style="color:${metrics.criticalFailures>0?'red':'green'}">${metrics.criticalFailures}</td><td><b>NPT Hours (24h)</b></td><td>${metrics.nptHoursYesterday?.toFixed(1)}</td></tr>
<tr><td><b>Certs Expiring 30d</b></td><td>${metrics.certsExpiring30d}</td><td><b>Fleet Availability</b></td><td>${metrics.avgAvailability?.toFixed(1)}%</td></tr>
<tr><td><b>Deferred Tasks</b></td><td>${metrics.deferredTasks}</td><td><b>Open Observations</b></td><td>${metrics.openObservations}</td></tr>
</table>
<h2>🤖 AI Intelligence Summary</h2>
<div style="background:#f7f9fc;padding:16px;border-left:4px solid #3182ce">${aiSummary}</div>
<h2>🔍 Most Active Rigs (Last 24h)</h2>
${rigTable}
<br/><p><a href="https://rigmind.aquila-engineer.com/dashboard" style="background:#3182ce;color:white;padding:10px 20px;text-decoration:none;border-radius:4px">Open RigMind Dashboard →</a></p>
</body></html>`;

return [{ json: { emailHtml: html, subject: `RigMind Daily Report — ${date} | ${metrics.criticalFailures} Critical | ${metrics.openFailures} Open Failures` } }];
